select id, session_id, event_type, page, event_time, duration_sec, sum(duration_sec) over (partition by event_type, session_id order by cast(event_time as bigint) range between 7776000 preceding and current row) as duration_sec_sum_90d, sum(duration_sec) over (partition by session_id, page order by event_time, id rows between unbounded preceding and current row) as cumulative_duration_sec, first_value(page) ignore nulls over (partition by event_type order by duration_sec, id rows between unbounded preceding and current row) as first_known_page from web_events
